                        theta1=[theta1,theta];
                        Theta=ones(1,nf).*theta;

                        SPLsbp=Lwsb-10*log10(4*pi*r2)+surffit1((Theta),(stn)); 
                        toSPL=toSPL+(10.^(SPLsbp./10));

                                
    end
 SPLbp=10*log10(toSPL);
 for i=1:nf
     data(:,i) = dba_corr_func(f(i));
     SPL_A_corr(i)=SPLbp(i)+(dba_corr_func(f(i)));
 end

        SPL=[(SPL);SPLbp];
        totSPLbp=sum(10.^(SPLbp./10));
        SPLOA_1=10*log10(totSPLbp);
        SPLOA=[(SPLOA);SPLOA_1];
        OASPL = mean(SPLOA');
end



